base.shop/receipt.py:
from shop.catalog import product


def render(lines):
    """Plain-text receipt with one row per (sku, quantity) line."""
    rows = []
    for sku, quantity in lines:
        item = product(sku)
        unit = item.get("price", 0.0)
        rows.append(f"{quantity} x {item['name']} @ ${unit:.2f}")
    return "\n".join(rows)

